{
  global:
    /* Export everything except BoringSSL/OpenSSL symbols */
    *;
  local:
    /* Hide BoringSSL symbols to avoid conflict with system OpenSSL */
    SSL_*;
    ssl_*;
    EVP_*;
    evp_*;
    CRYPTO_*;
    crypto_*;
    BIO_*;
    bio_*;
    RSA_*;
    rsa_*;
    EC_*;
    ec_*;
    X509*;
    x509*;
    PEM_*;
    pem_*;
    PKCS*;
    pkcs*;
    ERR_*;
    err_*;
    OBJ_*;
    obj_*;
    ASN1_*;
    asn1_*;
    OPENSSL_*;
    openssl_*;
    SHA*;
    sha*;
    MD5*;
    md5*;
    AES_*;
    aes_*;
    DES_*;
    des_*;
    HMAC*;
    hmac*;
    HKDF_*;
    hkdf_*;
    DH_*;
    dh_*;
    DSA_*;
    dsa_*;
    ECDSA_*;
    ecdsa_*;
    ECDH_*;
    ecdh_*;
    BN_*;
    bn_*;
    RAND_*;
    rand_*;
    CONF_*;
    conf_*;
    ENGINE_*;
    engine_*;
    CMAC_*;
    cmac_*;
    HPKE_*;
    CBS_*;
    CBB_*;
    sk_*;
    i2d_*;
    d2i_*;
    GENERAL_NAME*;
    v2i_*;
    BASIC_CONSTRAINTS*;
    AUTHORITY_*;
    NAME_CONSTRAINTS*;
    DIST_POINT*;
    ACCESS_DESCRIPTION*;
    POLICY*;
    NOTICEREF*;
    USERNOTICE*;
    ISSUING_DIST_POINT*;
    OTHERNAME*;
    EDIPARTYNAME*;
    policy_*;
    BORINGSSL_*;
    boringssl_*;
    CHACHA20_*;
    chacha20_*;
    POLY1305_*;
    poly1305_*;
    ED25519_*;
    ed25519_*;
    X25519_*;
    x25519_*;
    SPAKE2_*;
    spake2_*;
    TRUST_TOKEN_*;
    trust_token_*;
    lshpack_*;
    lsqpack_*;
    xxh*;
    XXH*;
};
